local WineVintner = {}
local PRODUCTS = {
    table_wine = { name = "Namizno vino", grapeCost = 3, waterCost = 1, time = 4, cost = 25, alcoholContent = 8, happiness = 2, description = "Namizno vino za vsakdanjo rabo." },
    red_wine = { name = "Rdeče vino", grapeCost = 4, oakCost = 1, waterCost = 1, time = 6, cost = 70, alcoholContent = 11, happiness = 3, prestige = 2, description = "Rdeče vino starano v hrastovem sodu." },
    white_wine = { name = "Belo vino", grapeCost = 4, oakCost = 1, waterCost = 1, time = 6, cost = 70, alcoholContent = 11, happiness = 3, prestige = 2, description = "Belo vino z nežnim okusom." },
    spiced_wine = { name = "Začinjeno vino", grapeCost = 4, spiceCost = 1, honeyCost = 1, waterCost = 1, time = 8, cost = 180, alcoholContent = 14, happiness = 5, prestige = 5, description = "Začinjeno vino z medom." },
    vintage_wine = { name = "Staro vino", grapeCost = 6, oakCost = 2, silverCost = 1, waterCost = 2, time = 12, cost = 480, alcoholContent = 16, happiness = 8, prestige = 12, description = "Starano vino za plemiče." },
    royal_grand_wine = { name = "Kraljevski veliki vino", grapeCost = 10, goldCost = 1, silverCost = 1, jewelCost = 1, oakCost = 3, honeyCost = 2, waterCost = 3, time = 18, cost = 1600, alcoholContent = 22, happiness = 18, prestige = 40, description = "Veliki kraljevski vino z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Vinarska delavnica", cost = { gold = 320, wood = 180 }, upkeep = 8, qualityBonus = 5 },
    winery = { name = "Vinska klet", cost = { gold = 1100, wood = 300, stone = 400, grape = 10 }, upkeep = 28, qualityBonus = 18 },
    aging_barrel_room = { name = "Sodna starilnica", cost = { gold = 2500, wood = 450, stone = 700, silver = 40, oak = 10 }, upkeep = 65, qualityBonus = 30 },
    royal_wine_atelier = { name = "Kraljevski atelje vina", cost = { gold = 10000, wood = 700, stone = 1200, gold = 80, jewel = 25 }, upkeep = 200, qualityBonus = 55, prestigeBonus = 45 },
}
WineVintner.grapeStock = 22; WineVintner.waterStock = 18; WineVintner.oakStock = 12; WineVintner.spiceStock = 10; WineVintner.honeyStock = 10; WineVintner.silverStock = 8; WineVintner.goldStock = 6; WineVintner.jewelStock = 6
WineVintner.productStock = {}; WineVintner.buildings = {}; WineVintner.maker = nil; WineVintner.activeMaking = {}; WineVintner.totalProducts = 0; WineVintner.dayTimer = 0
function WineVintner.init() WineVintner.grapeStock=22; WineVintner.waterStock=18; WineVintner.oakStock=12; WineVintner.spiceStock=10; WineVintner.honeyStock=10; WineVintner.silverStock=8; WineVintner.goldStock=6; WineVintner.jewelStock=6; WineVintner.productStock={}; WineVintner.buildings={}; WineVintner.maker=nil; WineVintner.activeMaking={}; WineVintner.totalProducts=0; WineVintner.dayTimer=0; print("[WineVintner] Royal Wine Vintner System initialized (6 products, 4 buildings)") end
function WineVintner.hireMaker(n,s) s=s or math.random(50,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WineVintner.maker={name=n or ("Vinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vinar najet: %s (spretnost: %d)",WineVintner.maker.name,s),"success") end; return true end
function WineVintner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WineVintner.build(id) local ok,e=WineVintner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WineVintner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WineVintner.getQualityBonus() local b=0; for _,bd in ipairs(WineVintner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WineVintner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.grapeCost and WineVintner.grapeStock<(d.grapeCost or 0) then return false,"Premalo grozdja" end; if d.waterCost and WineVintner.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.oakCost and WineVintner.oakStock<(d.oakCost or 0) then return false,"Premalo hrasta" end; if d.spiceCost and WineVintner.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.honeyCost and WineVintner.honeyStock<(d.honeyCost or 0) then return false,"Premalo medu" end; if d.silverCost and WineVintner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WineVintner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WineVintner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #WineVintner.buildings==0 then return false,"Potrebna delavnica" end; if not WineVintner.maker then return false,"Potreben vinar" end; return true end
function WineVintner.make(pt,qty) qty=qty or 5; local ok,e=WineVintner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.grapeCost then WineVintner.grapeStock=WineVintner.grapeStock-d.grapeCost*qty end; if d.waterCost then WineVintner.waterStock=WineVintner.waterStock-d.waterCost*qty end; if d.oakCost then WineVintner.oakStock=WineVintner.oakStock-d.oakCost*qty end; if d.spiceCost then WineVintner.spiceStock=WineVintner.spiceStock-d.spiceCost*qty end; if d.honeyCost then WineVintner.honeyStock=WineVintner.honeyStock-d.honeyCost*qty end; if d.silverCost then WineVintner.silverStock=WineVintner.silverStock-d.silverCost*qty end; if d.goldCost then WineVintner.goldStock=WineVintner.goldStock-d.goldCost*qty end; if d.jewelCost then WineVintner.jewelStock=WineVintner.jewelStock-d.jewelCost*qty end; local t=d.time; if WineVintner.maker then t=math.max(1,t-math.floor(WineVintner.maker.skill/12)) end; table.insert(WineVintner.activeMaking,{id="wine_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,alcoholContent=d.alcoholContent or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WineVintner.completeMaking(m) local q=1.0+(WineVintner.getQualityBonus()/100); if WineVintner.maker then q=q+(WineVintner.maker.skill/180) end; q=math.min(2.0,q); WineVintner.productStock[m.productType]=(WineVintner.productStock[m.productType] or 0)+m.quantity; WineVintner.totalProducts=WineVintner.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WineVintner.maker then WineVintner.maker.itemsMade=WineVintner.maker.itemsMade+m.quantity; if math.random()<0.20 then WineVintner.maker.skill=math.min(100,WineVintner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vino izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"wine.completed",{productName=m.productName,alcoholContent=m.alcoholContent,happiness=m.happiness}) end end
function WineVintner.update(dt) if not _G.state then return end; WineVintner.dayTimer=WineVintner.dayTimer+dt; if WineVintner.dayTimer>=30 then WineVintner.dayTimer=0; for i=#WineVintner.activeMaking,1,-1 do local m=WineVintner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WineVintner.completeMaking(m); table.remove(WineVintner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WineVintner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WineVintner.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WineVintner.getStats() return {grapeStock=WineVintner.grapeStock,waterStock=WineVintner.waterStock,oakStock=WineVintner.oakStock,spiceStock=WineVintner.spiceStock,honeyStock=WineVintner.honeyStock,silverStock=WineVintner.silverStock,goldStock=WineVintner.goldStock,jewelStock=WineVintner.jewelStock,productStock=WineVintner.productStock,numBuildings=#WineVintner.buildings,hasMaker=WineVintner.maker~=nil,makerName=WineVintner.maker and WineVintner.maker.name or "—",makerSkill=WineVintner.maker and WineVintner.maker.skill or 0,activeMaking=#WineVintner.activeMaking,totalProducts=WineVintner.totalProducts} end
return WineVintner
